questionvariables.text:
/* List of dimensions: [radius, height] */
list_of_the_values:[
    [3,8],[4,10],[5,12],[6,15],[7,16],
    [8,20],[9,24],[10,25],[12,30],[15,36],
    [16,40],[18,45],[20,48],[24,60],[25,64]
];

/* Randomly select one set of dimensions */
index:1+rand(length(list_of_the_values));
choose_one:list_of_the_values[index];

radius:choose_one[1];
height:choose_one[2];

/* Use π ≈ 22/7 */
pi_value:22/7;

/* Surface areas */
Cylinder_curved_area:2*pi_value*radius*height;
Hemisphere_curved_area:2*pi_value*radius^2;
Cylinder_base_area:pi_value*radius^2;

/* Correct total external surface area */
Total_surface_area:round(Cylinder_curved_area + Hemisphere_curved_area + Cylinder_base_area);


/* Common student misconceptions */

/* Uses sphere instead of hemisphere */
Sphere_mistake:round(Cylinder_curved_area+4*pi_value*radius^2+Cylinder_base_area);

/* Omits the cylinder base */
No_base_mistake:round(Cylinder_curved_area+Hemisphere_curved_area);

/* Includes both circular bases of the cylinder */
Two_bases_mistake:round(Cylinder_curved_area +Hemisphere_curved_area + 2*Cylinder_base_area);
